frappe.ready(() => {
get_student_data();
});
function get_student_data() {
	const queryString = window.location.search;
	const urlParams = new URLSearchParams(queryString);
	const payment_request = urlParams.get('payment_request');
	frappe.call({
		method: "edu_quality.fees.page.payment_redirect.get_payment_details",
		type: "GET",
		args: {
			doc: payment_request
		},
		callback: function (r) {
		    if (r.message == "cancelled"){
		        "The payment link is invalidated or cancelled! Please check email for new link or contact the school!"
		    }
		    else{
			var content = document.getElementById('chart');
			var html =
				`<div class="container mt-4 mb-4 p-3 d-flex justify-content-center">
    <div class="card p-4">
        <div class=" image d-flex flex-column justify-content-center align-items-center"> <button
                class="btn btn-secondary"> <img src="https://fees.walnutedu.in/bootstrap/images/walnut_icon.png" height="100"
                    width="100" /></button> <span class="name mt-3">` + r.message.student_name + `</span> <span
                class="idd">` + r.message.student_id + `</span>
            <div class="d-flex flex-row justify-content-center align-items-center gap-2">` 
			if(r.message.due_date!=null){
			html = html +`<span class="idd1"><b>Due Date:</b> </span> 
				<span class="idd1">`+ r.message.due_date + `</span>
				</div>` }
			html = html +`<span class="idd1"><b>Payment Term:</b>`+ r.message.term +  `</span>
				</div>` 
			html = html + `<div class="d-flex flex-row justify-content-center align-items-center mt-3"> 
				<span class="number">`+ r.message.due_amount + ` <span class="follow">INR</span></span></div>
				<div class="d-flex flex-row justify-content-center align-items-center mt-3"><span class="number">Breakup</span></div>
				<div class="table-responsive-md">
				<table class="table" id='table'>
  <thead>
    <tr>
      <th scope="col">#</th>
      <th scope="col">Fee Category</th>
      <th scope="col">Company</th>
      <th scope="col">Amount</th>
    </tr>
  </thead>
  <tbody>
  `;
  	var breakup = r.message.breakup;
	var i = 1;
	breakup.forEach(element => {
		html = html + `<tr>
		<th scope="row">`+ String(i) +`</th>
		<td>`+ element.fees_category +`</td>
		<td>`+ element.company +`</td>
		<td>`+ element.amount + `</td>`;
        if(r.message.status == "Paid"){
            html = html + `<td><a id="url" href="`+ r.message.receipt_url + "&category=" + encodeURIComponent(element.fees_category) + `"><button class="btn-dark">Download</button></a></td>`;
        }
	    html = html + `</tr>`;
	  i = i+1;
	});
	
	var discounts = r.message.discounts;
	if(discounts.referral_discount!=0){
		html = html + `<tr>
		<th scope="row">`+ String(i) +`</th>
		<td>Referral Discount</td>
		<td>`+ discounts.referral_discount_company +`</td>
		<td>-₹ `+ discounts.referral_discount + `</td>`;
	    html = html + `</tr>`;
	    }
	    if(discounts.other_discount!=0){
    	    i = i+1
    	    html = html + `<tr>
    		<th scope="row">`+ String(i) +`</th>
    		<td>Other Discount</td>
    		<td>`+ discounts.other_discount_company +`</td>
    		<td>-₹ `+ discounts.other_discount + `</td>`;
    	    html = html + `</tr>`;
	    }
	
	html = html + `</tbody>
	</table></div><div class=" image d-flex flex-column justify-content-center align-items-center">`;
	if(r.message.status != "Paid"){
	payment_method = `<span class ="follow">Payment Method:</span>
	<span><select class="form-control" id="payment_method" onchange="change_payment()">
	<option value="UPI">UPI</option>
	<option value="Net Banking">NET Banking</option>
	<option value="Credit Card">Credit Card</option>
	<option value="Debit card">Debit card</option>
	<option value="Mobile Wallet">Mobile Wallet</option>
	</select></span>`;

	
	if (r.message.undertaking_url !== null){
	    if(r.message.undertaking_accepted){
	        check_box = `<input type="checkbox" id="undertaking" name="undertaking" onclick="handleUndertaking()" checked>`;
        	payment_button = `<div class=" d-flex mt-2"> <a class="btn-dark p-3" id="url" role="button" href="`+ r.message.payment_url + `">Proceed To Pay</a> </div>`;
	    }else{
	        check_box = `<input type="checkbox" class="disabled" id="undertaking" name="undertaking" onclick="handleUndertaking()">`;
        	payment_button = `<div class=" d-flex mt-2"> <a class="btn-dark disabled p-3" id="url" role="button" href="`+ r.message.payment_url + `">Proceed To Pay</a> </div>`;
	    }
    	otp = `
        	<div class="form-inline m-1 hidden" id="otp-area">
                <input type="text" class="form-control p-5" id="otp" placeholder="Enter OTP">
                <button class="btn-dark m-3 p-1" onclick="verifyOtp()">Submit OTP</button>
            </div>
    	`;
    	undertaking = `<span>` + check_box +` <label for="undertaking">Accept Undertaking Before Making Payment <a href="` + r.message.undertaking_url +`" target='_blank'>Click here</a></label></span>`;
        html = html + undertaking + otp;
        
        html = html + payment_method + payment_button;
	}else{
    	payment_button = `<div class=" d-flex mt-2"> <a class="btn-dark p-3" id="url" role="button" href="`+ r.message.payment_url + `">Proceed To Pay</a> </div>`;
        html = html + payment_method + payment_button;
	}

	}
	html = html + `</div><div class="text mt-3"> <span>Note : If the receipt is not generated, but the amount is deducted from your account then please send an email with transaction details to 'feedback@walnutedu.in'. </span> </div>
	</div>
</div>
	</div>
	<style>
	* {
		margin: 0;
		padding: 0
	}
	
	body {
		background-color: #000
	}
	
	.card {
		width: 1000px;
		background-color: #efefef;
		border: none;
		cursor: pointer;
		transition: all 0.5s;
	}
	
	.image img {
		transition: all 0.5s
	}
	
	.card:hover .image img {
		transform: scale(1.5)
	}
	
	.btn {
		height: 140px;
		width: 140px;
		border-radius: 50%
	}
	
	.name {
		font-size: 22px;
		font-weight: bold
	}
	
	.idd {
		font-size: 14px;
		font-weight: 600
	}
	
	.idd1 {
		font-size: 12px
	}
	
	.number {
		font-size: 22px;
		font-weight: bold
	}
	
	.follow {
		font-size: 12px;
		font-weight: 500;
		color: #444444
	}
	
	.btn1 {
		height: 40px;
		width: 150px;
		border: none;
		background-color: #000;
		color: #aeaeae;
		font-size: 15px
	}
	
	.text span {
		font-size: 13px;
		color: #545454;
		font-weight: 500
	}
	
	.icons i {
		font-size: 19px
	}
	
	hr .new1 {
		border: 1px solid
	}
	
	.join {
		font-size: 14px;
		color: #a0a0a0;
		font-weight: bold
	}
	
	.date {
		background-color: #ccc
	}
	#url{
	    text-decoration: none;
	}
	
	#url.disabled {
        pointer-events: none;
        color: gray;
        text-decoration: none;
        cursor: not-allowed;
    }
    
    @media screen and (max-width: 767px) {
    .table-responsive {
        width: 100%;
        margin-bottom: 15px;
        overflow-x: scroll;;
        overflow-y: hidden;
        -webkit-overflow-scrolling: touch;
        -ms-overflow-style: scrollbar;
        border: 1px solid #DDD;
    }
}
	
	</style>`;
	content.innerHTML = html;
		}
		}

	});
}



var charge = 0;
function change_payment(){
    const queryString = window.location.search;
    const urlParams = new URLSearchParams(queryString);
    const payment_request = urlParams.get('payment_request');
	var method = document.getElementById("payment_method").value;
	frappe.call({
		method: "payment_charge",
		type: "GET",
		args: {
			pm: method,
			pr: payment_request
		},
		callback: function (r) {
			var charge = r.message.charge;
			row = document.getElementById("payment_charge_row");
			if(row){
				row.remove();

			}
			if(charge>0){
				var table = document.getElementById("table");
				table.innerHTML = table.innerHTML + `<tr id="payment_charge_row">
				<th scope="row">`+ String(table.rows.length) +`</th>
				<td>`+ "Payment Charges" +`</td>
				<td>`+ String(charge) + `%</td>
			  </tr>`;
			}
			if(r.message.url){
				url = document.getElementById("url");
				url.href = r.message.url;
			}
		}

	});
}

function download_Receipt(){
    const queryString = window.location.search;
	const urlParams = new URLSearchParams(queryString);
	const payment_request = urlParams.get('payment_request');
	frappe.call({
		method: "edu_quality.fees.page.payment_redirect.payment_receipt",
		type: "GET",
		args: {
			hash: payment_request
		},
		callback: function (r) {
			window.location.replace(r.message);
		}

	});
}

function redirectToPayment() {
	const queryString = window.location.search;
	const urlParams = new URLSearchParams(queryString);
	const payment_request = urlParams.get('payment_request');
	frappe.call({
		method: "generate_payment_url",
		type: "GET",
		args: {
			doc: payment_request
		},
		callback: function (r) {
			window.location.replace(r.message);
		}

	});
}

const queryString = window.location.search;
const urlParams = new URLSearchParams(queryString);
const payment_request = urlParams.get('payment_request');

function handleUndertaking() {
    const undertaking = document.getElementById('undertaking');
    
    if (undertaking.checked) {
        sendOtp();
    }else{
        url.classList.add('disabled');
    }
}

function submitUndertaking() {
    const otp = document.getElementById('otp').value;
    fetch('https://ipinfo.io/json')
        .then(response => response.json())
        .then(data => {
            let userIpAddress = data.ip;
            let userAgentInfo = navigator.userAgent;
            frappe.call({
                method: 'edu_quality.public.py.utils.handle_undertaking_submission',
                args: {
                    ip_address: userIpAddress,
                    browser_info: userAgentInfo,
                    payment_request: payment_request,
                    otp: otp
                },
                callback: function (response) {
                    if (response.message === 'success') {
                        // Data sent successfully.
                    } else {
                        // Handle the error here.
                    }
                },
                error: function (xhr, textStatus, errorThrown) {
                    console.error('Error sending data:', errorThrown);
                },
            });
        });
}


function showAlert(message, indicator){
    frappe.show_alert({
        message: __(message),
        indicator: indicator
    });
}


function sendOtp(){
    const otp_area = document.getElementById('otp-area');
    frappe.call({
		method:"edu_quality.public.py.undertaking.generate_undertaking_otp",
		args: {
			"payment_hash":payment_request,
		},
		callback: function(r) {
		    if (r.message === true){
		        showAlert("OTP has been sent successfully.", 'green');
                otp_area.classList.remove('hidden');
		    }
		    else{
      	        showAlert("Error while sending OTP.", 'red');
		    }
		}
	});
}

function verifyOtp(){
    const url = document.getElementById('url');
    const otp = document.getElementById('otp');
    const otp_area = document.getElementById('otp-area');
	
    frappe.call({
		method:"edu_quality.public.py.undertaking.verify_undertaking_otp",
		args: {
			"payment_hash":payment_request,
			"otp": otp.value
		},
		callback: function(r) {
		    if(r.message === true){
		        submitUndertaking();
                showAlert('OTP Verified Successfully', 'green');
                otp_area.classList.add('hidden');
                url.classList.remove('disabled');
		    }else{
                showAlert('Incorrect OTP Entered, please try again.', 'red');
                otp.classList.add("border", "border-danger");
                url.classList.add('disabled');
		    }
		}
	});
}
